// Fixed script templates of the vendor FPGA tools (Aşama 6k-1).
//
// The page sends only a checked option line (vendorPolicy.cjs). This module turns the parsed request into the files
// the main process writes next to the page's files (a Tcl script, a project file) and the tool's command line. The
// templates are constants; the only values put into them are the part, the top-level name and file names, and
// each one is checked again here against a character set with no Tcl meaning, so a value can never become a
// command. Generated file names start with "lds_" or are <top>.qpf: types the page may not send.
'use strict';

const { IDENT_RE, FILE_RE, VIVADO_PART_RE, QUARTUS_PART_RE, ISE_PART_RE, ISE_CPLD_RE, POSITION_RE } = require('./vendorPolicy.cjs');

/** A value for a template, or an exception: the policy should have refused it already */
function word(value, re) {
  if (typeof value !== 'string' || !re.test(value) || /[\s{}[\]$\\";%]/.test(value)) throw new Error(`Template value refused: ${value}`);
  return value;
}

const isVhdl = (name) => /\.(vhd|vhdl)$/i.test(name);
const isSv = (name) => /\.sv$/i.test(name);

/** Script header: which template made the file (shown in the tool's log) */
const HEADER = '# Generated by LogicDesign Studio from a fixed template. Do not edit.';

/**
 * Vivado non-project batch build: read the sources and the .xdc, synthesize, implement, write <top>.bit. Run as
 * vivado -mode batch -source lds_vivado.tcl.
 */
function vivadoBuild(req) {
  const part = word(req.part, VIVADO_PART_RE);
  const top = word(req.top, IDENT_RE);
  const lines = [HEADER];
  for (const s of req.sources) {
    const f = word(s, FILE_RE);
    lines.push(isVhdl(f) ? `read_vhdl {${f}}` : isSv(f) ? `read_verilog -sv {${f}}` : `read_verilog {${f}}`);
  }
  lines.push(
    `read_xdc {${word(req.constraints, FILE_RE)}}`,
    `synth_design -top {${top}} -part {${part}}`,
    'opt_design',
    'place_design',
    'route_design',
    `write_bitstream -force {${top}.bit}`,
    'exit',
    ''
  );
  return {
    files: { 'lds_vivado.tcl': lines.join('\n') },
    args: ['-mode', 'batch', '-nojournal', '-nolog', '-notrace', '-source', 'lds_vivado.tcl'],
  };
}

/** The die of a checked 7-series part: xc7a35tcpg236-1 -> xc7a35t, xc7z007sclg225-1 -> xc7z007s */
function vivadoDie(part) {
  const m = /^(xc7[aksz]\d{1,3}t?s?)[a-z]{2,5}\d{3,4}-[1-3]L?$/.exec(word(part, VIVADO_PART_RE));
  if (!m) throw new Error(`Template value refused: ${part}`);
  return m[1];
}

/**
 * Vivado hardware manager: load a bitstream into the SRAM of the board's FPGA over JTAG. connect_hw_server without
 * a URL connects to localhost:3121 and starts the hw_server bundled with this Vivado when none runs there; the page
 * never names a server. Every JTAG target is opened in turn and the first one whose chain holds a device of the
 * part's die is programmed, so another board on another cable is never touched. The "LDS-ERROR:" lines are read by
 * the page (src/fpga/flow/program.ts classifyVivadoProgramOutput); each has its own exit code.
 *
 * Vivado leaves the hw_server it started running after it exits (as its GUI does); that server keeps the cable
 * open, so openFPGALoader cannot use the same cable until hw_server ends.
 */
function vivadoProgram(req) {
  const die = vivadoDie(req.part);
  const bit = word(req.bitstream, FILE_RE);
  const lines = [
    HEADER,
    'open_hw_manager',
    'connect_hw_server',
    'set lds_targets [get_hw_targets -quiet]',
    'if {[llength $lds_targets] == 0} {',
    '  puts "LDS-ERROR: no hardware target (no JTAG cable found)"',
    '  exit 3',
    '}',
    'set lds_device {}',
    'set lds_seen 0',
    'foreach lds_target $lds_targets {',
    '  if {[catch {open_hw_target $lds_target} lds_message]} {',
    '    puts "LDS-INFO: cannot open $lds_target: $lds_message"',
    '    continue',
    '  }',
    '  set lds_all [get_hw_devices -quiet]',
    '  incr lds_seen [llength $lds_all]',
    `  set lds_device [lindex [get_hw_devices -quiet -filter {PART =~ "${die}*"}] 0]`,
    '  if {$lds_device ne {}} { break }',
    '  puts "LDS-INFO: $lds_target holds: $lds_all"',
    '  close_hw_target $lds_target',
    '}',
    'if {$lds_device eq {}} {',
    '  if {$lds_seen == 0} {',
    '    puts "LDS-ERROR: no FPGA on the chain (is the board powered?)"',
    '    exit 4',
    '  }',
    `  puts "LDS-ERROR: no matching FPGA: no ${die} on any JTAG chain"`,
    '  exit 5',
    '}',
    'puts "LDS-INFO: programming $lds_device"',
    'current_hw_device $lds_device',
    `set_property PROGRAM.FILE {${bit}} $lds_device`,
    'set_property PROBES.FILE {} $lds_device',
    'program_hw_devices $lds_device',
    'close_hw_target',
    'exit 0',
    '',
  ];
  return {
    files: { 'lds_program.tcl': lines.join('\n') },
    args: ['-mode', 'batch', '-nojournal', '-nolog', '-notrace', '-source', 'lds_program.tcl'],
  };
}

/**
 * Quartus full compile (analysis, fitter, assembler, timing) of revision <top>: the page's <top>.qsf holds the
 * device, sources and pins (checked line by line); the project file is written here, and one fixed line is
 * appended to the .qsf: SYNTHESIS is defined, as Yosys and Vivado do by themselves (the generated Verilog keeps
 * its simulation-only code, a $time check, inside `ifndef SYNTHESIS). quartus_sh --flow compile prints the
 * modules' messages as text (a Tcl execute_flow would print them in a machine format) and exits non-zero on a
 * failed step.
 */
function quartusCompile(req) {
  word(req.part, QUARTUS_PART_RE);
  const top = word(req.top, IDENT_RE);
  return {
    files: { [`${top}.qpf`]: `${HEADER}\nPROJECT_REVISION = "${top}"\n` },
    append: { [word(req.constraints, FILE_RE)]: '\n# Added by LogicDesign Studio\nset_global_assignment -name VERILOG_MACRO "SYNTHESIS=1"\n' },
    args: ['--flow', 'compile', top],
  };
}

/**
 * Quartus programmer: quartus_pgm loads the file over JTAG through the first cable the JTAG server knows (-c 1, the
 * USB-Blaster of a single plugged-in board): a .sof into an FPGA's SRAM, a .pof into a CPLD's own memory. The
 * page never names a cable. The operation "p;<file>" is one argument handed to quartus_pgm.exe directly (no
 * shell or cmd.exe reads it), and the file name holds no ";" or spaces (FILE_RE). The JTAG server it talks to is
 * the Windows service Quartus installs (jtagserver), which keeps running as before.
 */
function quartusProgram(req) {
  word(req.part, QUARTUS_PART_RE);
  const file = word(req.bitstream, FILE_RE);
  if (!/\.(sof|pof)$/i.test(file)) throw new Error(`Template value refused: ${file}`);
  return { program: 'quartus_pgm', files: {}, args: ['-c', '1', '-m', 'JTAG', '-o', `p;${file}`] };
}

/**
 * iMPACT boundary-scan batch: find the cable (setCable -port auto: a Xilinx Platform Cable USB or a parallel
 * cable), identify the JTAG chain, assign the file to the device at the board's chain position and program it. A
 * .bit goes into an FPGA's SRAM; a .jed is erased, written and verified in a CPLD's own memory (-e -v). iMPACT
 * checks the file's device against the one it finds at that position. The page sends only the part, the
 * position and the file name; iMPACT stops at the first failing command and exits non-zero (a missing cable:
 * "Cable autodetection failed.", exit code 1), and it leaves no process running.
 */
function iseProgram(req) {
  word(req.part, ISE_PART_RE);
  const position = word(req.position, POSITION_RE);
  const file = word(req.bitstream, FILE_RE);
  const jed = /\.jed$/i.test(file);
  if (!jed && !/\.bit$/i.test(file)) throw new Error(`Template value refused: ${file}`);
  if (jed !== ISE_CPLD_RE.test(req.part)) throw new Error(`Template value refused: ${file}`);
  const lines = [
    'setMode -bs',
    'setCable -port auto',
    'Identify -inferir',
    'identifyMPM',
    `assignFile -p ${position} -file "${file}"`,
    jed ? `Program -p ${position} -e -v` : `Program -p ${position}`,
    'quit',
    '',
  ];
  return { program: 'impact', files: { 'lds_impact.cmd': lines.join('\n') }, args: ['-batch', 'lds_impact.cmd'] };
}

/** One step of the ISE FPGA chain, as ISE's own process "Generate Programming File" runs them */
function iseStep(req) {
  // Programming names no top level
  if (req.step === 'program') return iseProgram(req);
  const top = word(req.top, IDENT_RE);
  const part = req.part === null ? null : word(req.part, ISE_PART_RE);
  switch (req.step) {
    case 'xst': {
      const prj = req.sources.map((s) => `${isVhdl(s) ? 'vhdl' : 'verilog'} work "${word(s, FILE_RE)}"`);
      // -define SYNTHESIS: XST does not define it by itself (see quartusCompile)
      const xst = ['run', '-ifn lds_xst.prj', '-ifmt mixed', `-top ${top}`, `-ofn ${top}.ngc`, '-ofmt NGC', `-p ${part}`, '-define {SYNTHESIS=1}'];
      return {
        program: 'xst',
        files: { 'lds_xst.prj': `${prj.join('\n')}\n`, 'lds_xst.xst': `${xst.join('\n')}\n` },
        args: ['-ifn', 'lds_xst.xst', '-ofn', `${top}.syr`],
      };
    }
    case 'ngdbuild':
      return { program: 'ngdbuild', files: {}, args: ['-p', part, '-uc', word(req.constraints, FILE_RE), `${top}.ngc`, `${top}.ngd`] };
    case 'map':
      return { program: 'map', files: {}, args: ['-p', part, '-w', '-o', `${top}_map.ncd`, `${top}.ngd`, `${top}.pcf`] };
    case 'par':
      return { program: 'par', files: {}, args: ['-w', `${top}_map.ncd`, `${top}.ncd`, `${top}.pcf`] };
    case 'bitgen':
      return { program: 'bitgen', files: {}, args: ['-w', `${top}.ncd`, `${top}.bit`, `${top}.pcf`] };
    // The CPLD chain (CoolRunner-II, XC9500), as ISE's "Generate Programming File" for a CPLD: cpldfit fits the
    // translated design and writes <top>.vm6, hprep6 turns that into the JEDEC fuse file <top>.jed
    case 'cpldfit':
      return { program: 'cpldfit', files: {}, args: ['-p', part, `${top}.ngd`] };
    case 'hprep6':
      return { program: 'hprep6', files: {}, args: ['-s', 'IEEE1149', '-n', top, '-i', top] };
    default:
      throw new Error(`Unknown ISE step ${req.step}`);
  }
}

/** { program?, files, args } of a checked request; program is the executable next to the install's (ISE steps, quartus_pgm) */
function scriptFor(tool, req) {
  if (tool === 'vivado' && req.step === 'build') return vivadoBuild(req);
  if (tool === 'vivado' && req.step === 'program') return vivadoProgram(req);
  if (tool === 'quartus' && req.step === 'compile') return quartusCompile(req);
  if (tool === 'quartus' && req.step === 'program') return quartusProgram(req);
  if (tool === 'ise') return iseStep(req);
  throw new Error(`No template for ${tool} ${req.step}`);
}

module.exports = { scriptFor, vivadoBuild, vivadoProgram, vivadoDie, quartusCompile, quartusProgram, iseStep, iseProgram };
